fn named_by_use<'e>(body: Option<&'e Body>, call_sites: &'e CallSites) -> rustc_hash::FxHashSet<&'e str> {
    let mut named: rustc_hash::FxHashSet<&str> = call_sites.passed.iter().map(|(name, _)| name.as_str()).collect();
